Sample the Catmull-Rom route into a cumulative-length table; per stop store arrive/depart times; head position = lookup(length(t)); drawn path = dasharray up to the head; remainder dashed (6/4) in #9c2a1c. Camera zooms out on long legs, in on arrival. Basma's map-journey already has `catmull()` + `INK.at(route,u)` to build on.
// lens[i] = cumulative length at sample i; stops[k] = {arrive, depart, s}
function headS(t) { let s = 0;
  for (const [k, st] of stops.entries()) {
    if (t < st.arrive) { const p = stops[k-1];
      const u = ease((t - p.depart) / (st.arrive - p.depart));
      return p.s + (st.s - p.s) * Math.max(0, u); }
    s = st.s; } return s; }        // dwell = clamp at st.s until depart

`project(lat, lon, {w:1000, h:820})`: lon scaled by cos(24°), bounds lon 34.4–56.2, lat 15.9–32.6; OUTLINE = 38 lon/lat points as one polygon; bubble r = max(6, √(v/max)·58) for regions, ·26 for cities, districts max(3.5, √·9); fill from the heat ramp MAP-46; 3 levels country → region → city with viewBox tween. Tests: `npx vitest run src/engine/fusion/sales/sales-geo-engine.test.ts` → 4/4 passed here. For video, drive the viewBox from the timeline instead of clicks.
const project = (lat, lon, { w = 1000, h = 820 } = {}) => {
  const k = Math.cos(24 * Math.PI / 180), x0 = 34.4 * k, x1 = 56.2 * k;
  return [ (lon * k - x0) / (x1 - x0) * w, (32.6 - lat) / (32.6 - 15.9) * h ]; };
const r = (v, max) => Math.max(6, Math.sqrt(v / max) * 58);   // regions

Rasterise continent polygons (world-atlas 110m) to a lat/lon dot grid ONCE (~2,000 dots, or a 2 px halftone with 15° graticule); each frame rotate (6–10 °/s) + tilt, project orthographically, cull back-facing (z < 0); dot size and alpha ∝ depth; add night shade and an atmosphere glow ring. Looks: navy keynote (#000 + glow #64d2ff, style:infographic), cream science-book (#efecdd, ink #1a1a18, red axis #c9452c, style:pm-hbcoop-de365c), black half-sphere with glowing rim and pings (style:pm-steventey-0d20e4). Build: `npm i d3@7.9.0 topojson-client@3.1.0 world-atlas@2.0.2`.
// dots: [{lon,lat}] sampled once from the land mask
const R = Math.PI / 180;
function drawGlobe(ctx, dots, rot, tilt, cx, cy, r) {
  for (const d of dots) {
    const l = (d.lon + rot) * R, p = d.lat * R;
    let x = Math.cos(p) * Math.sin(l), y = Math.sin(p), z = Math.cos(p) * Math.cos(l);
    [y, z] = [y * Math.cos(tilt*R) - z * Math.sin(tilt*R), y * Math.sin(tilt*R) + z * Math.cos(tilt*R)];
    if (z < 0) continue;                                  // back-face cull
    ctx.globalAlpha = 0.25 + 0.75 * z;
    ctx.fillRect(cx + x * r, cy - y * r, 1 + 1.5 * z, 1 + 1.5 * z); } }
